package com.chahinaz.pos.operations;import com.chahinaz.pos.sales.*;import com.chahinaz.pos.employee.Employee;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@Entity @Table(name="sale_return") public class SaleReturn{@Id public UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="original_sale_id")public Sale originalSale;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="employee_id")public Employee employee;@Column(name="register_session_id")public UUID registerSessionId;@Column(name="refund_usd",nullable=false,precision=12,scale=2)public BigDecimal refundUsd;@Column(name="refund_lbp",nullable=false,precision=18,scale=0)public BigDecimal refundLbp;@Enumerated(EnumType.STRING)@Column(name="refund_method",nullable=false,length=30)public PaymentType refundMethod;@Column(name="whish_manually_recorded",nullable=false)public boolean whishManuallyRecorded;@Column(nullable=false,length=500)public String reason;@Column(name="created_at",nullable=false)public Instant createdAt;@OneToMany(mappedBy="saleReturn",cascade=CascadeType.ALL)public List<SaleReturnItem> items=new ArrayList<>();protected SaleReturn(){}public SaleReturn(Sale s,Employee e,PaymentType m,String reason){id=UUID.randomUUID();originalSale=s;employee=e;refundMethod=m;this.reason=reason;createdAt=Instant.now();refundUsd=BigDecimal.ZERO.setScale(2);refundLbp=BigDecimal.ZERO.setScale(0);}}
